   (	"id_tali_kala_strip" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE ,
	"CREATE_AT" DATE,
	"CREATE_BY" NUMBER,
	"MODIFY_AT" DATE,
	"MODIFY_BY" NUMBER,
	"IS_DELETED" VARCHAR2(150 CHAR),
	"code" VARCHAR2(150 CHAR),
	"tali_id" NUMBER,
	"kala_strip_id" NUMBER,
	"DESCRIPTION" VARCHAR2(550 CHAR),
	"pricing_type" VARCHAR2(20 CHAR),
	"NUMBER_SERVICE" NUMBER
   ) ;

