   (	"JALALI_YEAR" NUMBER(4,0),
	"LAST_NUMBER" NUMBER
   ) ;

-- FA_TRAFFIC_CAR
CREATE TABLE "FA_TRAFFIC_CAR"
   (	"ID_TRAFFIC" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE ,
	"NAME_FAMILY" VARCHAR2(550),
	"TYPE_CAR" VARCHAR2(250),
	"NUMBER_PELAK" VARCHAR2(250),
	"TIME_ENTER" VARCHAR2(50),
	"TIME_EXIT" VARCHAR2(50) DEFAULT 50,
	"MAHE_BARGIRE" VARCHAR2(250),
	"TAHVIL_GIRANDEH" VARCHAR2(250),
	"VAREDAT" VARCHAR2(250),
	"TAKHLEH" VARCHAR2(250),
	"BAR_GIRI" VARCHAR2(250),
	"SADERATE" VARCHAR2(550),
	"GHABZE_BASKOL" NUMBER,
	"CREATE_AT" DATE,
	"CREATE_BY" NUMBER,
	"MODIFY_AT" DATE,
	"MODIFY_BY" NUMBER,
	"IS_DELETED" VARCHAR2(15 CHAR)
   ) ;

-- FA_TRANSPORT_COMPANY
CREATE TABLE "FA_TRANSPORT_COMPANY"
   (	"ID_COMPANY" NUMBER,
	"COMPANY_NAME" VARCHAR2(300 CHAR),
	"ADDRESS" VARCHAR2(1000 CHAR),
	"PHONE" VARCHAR2(50 CHAR),
	"NATIONAL_ID" VARCHAR2(30 CHAR),
	"ECONOMIC_CODE" VARCHAR2(40 CHAR),
	"IS_DELETED" VARCHAR2(3 CHAR) DEFAULT 'no',
	"CREATE_AT" DATE DEFAULT SYSDATE,
	"CREATE_BY" NUMBER,
	"MODIFY_AT" DATE,
	"MODIFY_BY" NUMBER
   ) ;

-- FA_USERS
CREATE TABLE "FA_USERS"
   (	"ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE ,
	"USERNAME" VARCHAR2(100),
	"PASSWORD_HASH" VARCHAR2(255),
	"FULL_NAME" VARCHAR2(200),
	"IS_ADMIN" VARCHAR2(3) DEFAULT 'no',
	"IS_ACTIVE" VARCHAR2(3) DEFAULT 'yes',
	"CREATE_AT" DATE DEFAULT SYSDATE,
	"CREATE_BY" VARCHAR2(100),
	"MODIFY_AT" DATE,
	"MODIFY_BY" VARCHAR2(100)
   ) ;
